SELECT ?artist (COUNT(?album) AS ?count) WHERE {
  ?album <http://dbpedia.org/property/producer> ?artist .
} GROUP BY ?artist ORDER BY DESC(?count) LIMIT 5

SELECT DISTINCT ?artist (COUNT(?album) AS ?albumCount) WHERE {
  ?album <http://dbpedia.org/property/producer> ?artist .
} GROUP BY ?artist ORDER BY DESC(?albumCount) LIMIT 5

SELECT ?kingdom (COUNT(?species) AS ?count) WHERE {
  ?species <http://dbpedia.org/property/status> ?status .
  ?species <http://dbpedia.org/property/regnum> ?kingdom .
  FILTER(CONTAINS(LCASE(STR(?status)), "endangered"))
} GROUP BY ?kingdom ORDER BY DESC(?count) LIMIT 3

SELECT ?kingdom (COUNT(?species) AS ?count) WHERE {
  ?species <http://dbpedia.org/property/regnum> ?kingdom .
} GROUP BY ?kingdom ORDER BY DESC(?count) LIMIT 3

